"use client";

import {
  AnimatePresence,
  LazyMotion,
  MotionConfig,
  domAnimation,
  m,
  useMotionValue,
  useReducedMotion,
  useSpring,
  type Transition
} from "framer-motion";
import { useCallback, useEffect, useMemo, useRef, useState, type CSSProperties, Suspense, lazy } from "react";

import styles from "@/components/codeflow-cat-showcase.module.css";

// Lazy load the 3D cat component
const CuteCat3D = lazy(() => import("@/components/CuteCat3D").then(mod => ({ default: mod.CuteCat3D })));

type SceneId =
  | "spec"
  | "ghost"
  | "implementation"
  | "heal"
  | "digitalTwin"
  | "vcr"
  | "heatmap"
  | "genetic"
  | "error"
  | "polish";

type ShowcaseProps = {
  activeScene?: SceneId;
  graphPhase?: "spec" | "implementation" | "integration" | null;
  ghostCount: number;
  unhealthy: boolean;
  verifiedAll: boolean;
};

type SceneDefinition = {
  id: SceneId;
  title: string;
  kicker: string;
  summary: string;
  accent: string;
  status: string;
  cue: string;
  telemetry: Array<{ label: string; value: string }>;
};

const SCENES: SceneDefinition[] = [
