        <path className={styles.tongue} d="M 222 160 Q 228 172 234 160" />
      </>
    );
  }

  if (sceneId === "error") {
    return (
      <m.path
        animate={reducedMotion ? { opacity: 0.95 } : { opacity: [0.35, 1, 0.35] }}
