export type OpencodeProvider = 
  | "anthropic"
  | "openai"
  | "google"
  | "azure"
  | "bedrock"
  | "cohere"
  | "groq"
  | "mistral"
  | "perplexity"
  | "openrouter"
  | "local";

export type OpencodeConfig = {
  provider: OpencodeProvider;
  apiKey?: string;
  model?: string;
  baseUrl?: string;
  logLevel?: "debug" | "info" | "warn" | "error";
  mcpServers?: McpServerConfig[];
  skills?: string[];
  hooks?: string[];
};

export type McpServerConfig = {
  name: string;
  command: string;
  args?: string[];
  env?: Record<string, string>;
};

export type OpencodeServerStatus = 
  | "stopped"
  | "starting"
  | "running"
  | "error";

export type OpencodeServerInfo = {
  status: OpencodeServerStatus;
  url?: string;
  error?: string;
  pid?: number;
};

export type AgentType = "build" | "plan" | "general";

export type AgentRequest = {
  type: AgentType;
  message: string;
  context?: {
    files?: string[];
    codeSnippets?: Array<{ path: string; content: string }>;
    previousMessages?: Array<{ role: "user" | "assistant"; content: string }>;
  };
};

export type AgentResponse = {
  success: boolean;
  response?: string;
  actions?: Array<{
    type: "file_edit" | "file_create" | "file_delete" | "bash_command" | "code_suggestion";
    payload: unknown;
  }>;
