            <button
              aria-label="Increase traversal depth"
              disabled={codeRagDepth >= 6}
              onClick={() => adjustCodeRagDepth(1)}
              type="button"
            >
              +
            </button>
          </div>
        </label>
        <div className="button-row">
          <button
            disabled={codeRagLoading || codeRagStatus !== "ready" || !codeRagQuery.trim()}
