                }
              }}
              type="button"
            >
              Use selection
            </button>
          ) : null}
        </div>

        {codeRagError ? (
          <div className="callout danger-callout">
            <p>{codeRagError}</p>
          </div>
        ) : null}

        {codeRagResult ? (
          <div className="coderag-results">
