            <torusGeometry args={[0.35, 0.04, 8, 32]} />
            <meshStandardMaterial color="#60a5fa" />
          </mesh>
          <mesh position={[0.35, 1.35, 1]}>
            <torusGeometry args={[0.35, 0.04, 8, 32]} />
            <meshStandardMaterial color="#60a5fa" />
          </mesh>
