function createInitialRoot(repoPath: string | null): FileTreeNode {
  return {
    path: ".",
    name: repoPath ? path.basename(repoPath) : "workspace",
    isDirectory: true,
    isExpanded: true,
    isLoading: true,
    children: undefined
  };
}

