    }

    const extraLibPath = toExtraLibPath(filePath);
    this.workspaceLibs.get(extraLibPath)?.dispose();
    this.workspaceLibs.set(extraLibPath, api.typescriptDefaults.addExtraLib(content, extraLibPath));
