const pruneEdges = (nodes: BlueprintNode[], edges: BlueprintEdge[]): BlueprintEdge[] => {
  const ids = new Set(nodes.map((n) => n.id));
  return edges.filter((e) => ids.has(e.from) && ids.has(e.to));
};

