import { describe, expect, it } from "vitest";

import { summarizeObservability } from "@/lib/blueprint/observability";
import type { BlueprintGraph } from "@/lib/blueprint/schema";
import { emptyContract } from "@/lib/blueprint/schema";

describe("summarizeObservability", () => {
  it("overlays spans and exposes recent spans/logs", () => {
    const graph: BlueprintGraph = {
      projectName: "Observed",
      mode: "essential",
      generatedAt: "2026-03-14T00:00:00.000Z",
      warnings: [],
      workflows: [],
      edges: [],
      nodes: [
        {
          id: "function:save",
          kind: "function",
          name: "saveTask",
          summary: "Save a task.",
          contract: { ...emptyContract(), summary: "Save a task." },
          sourceRefs: [],
          generatedRefs: [],
          traceRefs: []
        }
      ]
    };

    const summary = summarizeObservability(graph, {
      spans: [
        {
          spanId: "span-1",
          traceId: "trace-1",
          name: "saveTask",
          status: "error",
          durationMs: 8,
          runtime: "node",
          provenance: "observed"
        }
      ],
      logs: [
        {
          id: "log-1",
          level: "error",
          message: "save failed",
          blueprintNodeId: "function:save",
          runtime: "node",
          timestamp: "2026-03-14T00:00:00.000Z"
        }
      ]
    });

    expect(summary.graph.nodes[0].traceState?.status).toBe("error");
    expect(summary.latestLogs[0].message).toBe("save failed");
  });
});

import type {
  BlueprintGraph,
  ObservabilityLog,
  ObservabilitySnapshot,
  TraceSpan
} from "@/lib/blueprint/schema";
import { applyTraceOverlay } from "@/lib/blueprint/traces";

const pickLatest = <T extends { timestamp?: string; spanId?: string }>(items: T[], limit: number): T[] =>
  [...items]
    .sort((left, right) =>
      `${right.timestamp ?? right.spanId ?? ""}`.localeCompare(`${left.timestamp ?? left.spanId ?? ""}`)
    )
    .slice(0, limit);

export const overlayObservability = (
  graph: BlueprintGraph,
  snapshot: Pick<ObservabilitySnapshot, "spans" | "logs">
): BlueprintGraph => {
  const tracedGraph = applyTraceOverlay(graph, snapshot.spans);
  const nodeLogCounts = new Map<string, number>();

  for (const log of snapshot.logs) {
    if (!log.blueprintNodeId) {
      continue;
    }

    nodeLogCounts.set(log.blueprintNodeId, (nodeLogCounts.get(log.blueprintNodeId) ?? 0) + 1);
  }

  return {
    ...tracedGraph,
    nodes: tracedGraph.nodes.map((node) => ({
      ...node,
      contract: {
        ...node.contract,
        notes:
          nodeLogCounts.get(node.id) && !node.contract.notes.some((note) => note.startsWith("Logs observed:"))
            ? [...node.contract.notes, `Logs observed: ${nodeLogCounts.get(node.id)}`]
            : node.contract.notes
      }
    }))
  };
};

export const summarizeObservability = (
  graph: BlueprintGraph,
  snapshot: Pick<ObservabilitySnapshot, "spans" | "logs">
): {
  graph: BlueprintGraph;
  latestSpans: TraceSpan[];
  latestLogs: ObservabilityLog[];
} => ({
  graph: overlayObservability(graph, snapshot),
  latestSpans: pickLatest(snapshot.spans, 10),
  latestLogs: pickLatest(snapshot.logs, 10)
});

