const resolveCallTarget = (
  graph: BlueprintGraph,
  target: string
): BlueprintNode | undefined => {
  const byId = graph.nodes.find((n) => n.id === target);
  if (byId) return byId;

  return graph.nodes.find((n) => n.name === target);
};

