const hasJsDocSummary = (node: Node): string => {
  const maybeJsDocNode = node as Node & {
    getJsDocs?: () => Array<{ getDescription: () => string }>;
  };

  return maybeJsDocNode.getJsDocs
    ? maybeJsDocNode
        .getJsDocs()
        .map((doc) => doc.getDescription().trim())
        .filter(Boolean)
        .join(" ")
    : "";
};

