function writeStoredValue(kind: StorageKind, key: string, value: string | null) {
  const storage = getStorage(kind);
  if (!storage) {
    return;
  }

  if (value === null || value === "") {
    storage.removeItem(key);
    return;
  }

  storage.setItem(key, value);
}

