export function buildOpencodeConfig(
  provider: OpencodeProvider,
  apiKey: string,
  options: {
    model?: string;
    baseUrl?: string;
    logLevel?: OpencodeConfig["logLevel"];
    mcpServers?: OpencodeConfig["mcpServers"];
    skills?: string[];
    hooks?: string[];
  } = {}
): OpencodeConfig {
