  return {
    provider,
    apiKey,
    model: options.model || providerConfig.defaultModel,
    baseUrl: options.baseUrl,
    logLevel: options.logLevel || "info",
    mcpServers: options.mcpServers || [],
    skills: options.skills || [],
    hooks: options.hooks || [],
  };
}

