import { withCodeflowGovernance } from "@/lib/blueprint/prompt-governance";
import { blueprintGraphSchema } from "@/lib/blueprint/schema";
import { getNvidiaKeySource, requestNvidiaChatCompletion, resolveNvidiaApiKey } from "@/lib/blueprint/nvidia";
import { isOpencodeAvailable, sendToOpencode } from "@/lib/opencode/agent";

const requestSchema = z.object({
  graph: blueprintGraphSchema,
  nodeId: z.string().min(1),
  currentCode: z.string(),
  instruction: z.string().trim().optional(),
  retrievalQuery: z.string().trim().min(1).optional(),
  retrievalDepth: z.number().int().min(1).max(6).optional(),
  nvidiaApiKey: z.string().optional(),
  useOpencode: z.boolean().optional().default(false)
});

const responseSchema = z.object({
  summary: z.string(),
  code: z.string(),
  notes: z.array(z.string()).default([])
});

const SYSTEM_PROMPT = `You are a senior software engineer helping turn a blueprint node contract into implementation code.

Return ONLY valid JSON matching this schema:
{
  "summary": "short description of what changed",
  "code": "full replacement code for the current node",
  "notes": ["short implementation notes or follow-ups"]
}

Rules:
- Return a full replacement file in the "code" field, not a diff
- Use the supplied node contract as the source of truth
- Keep code aligned to the current file's likely language and role
- Include clear inline documentation comments when useful
- Preserve existing exported symbol names unless the blueprint contract requires otherwise
- If the current code is already strong, refine it instead of rewriting randomly
- Do not wrap the JSON in markdown fences`;

export async function POST(request: Request) {
  const startedAt = Date.now();

  try {
    const body = requestSchema.parse(await request.json());
    const useOpencode = body.useOpencode && isOpencodeAvailable();
    const apiKey = useOpencode ? null : resolveNvidiaApiKey(body.nvidiaApiKey);
    const keySource = useOpencode ? "opencode" : getNvidiaKeySource(body.nvidiaApiKey);
    const context = getNodeAssistanceContext(body.graph, body.nodeId);

    if (!context) {
      return NextResponse.json({ error: `Blueprint node ${body.nodeId} was not found.` }, { status: 404 });
    }

    const { node, relatedNodes, relatedEdges } = context;

    console.info("[CodeFlow] Code suggestion request received", {
      nodeId: body.nodeId,
      kind: node.kind,
      promptLength: body.instruction?.length ?? 0,
      keySource
    });

    if (!useOpencode && !apiKey) {
      // Check if OpenCode is available as fallback
      if (isOpencodeAvailable()) {
        body.useOpencode = true;
      } else {
        return NextResponse.json(
          { error: "No AI backend available. Either start OpenCode server or provide NVIDIA API key." },
          { status: 400 }
        );
      }
    }

    const retrievalContext = await resolveAgentRetrievalContext({
      node,
      relatedNodes,
      instruction: body.instruction,
      retrievalQuery: body.retrievalQuery,
      retrievalDepth: body.retrievalDepth
    });
    const userPrompt = `Suggest implementation code for this blueprint node.

Project: ${body.graph.projectName}
Node id: ${node.id}
Node name: ${node.name}
Node kind: ${node.kind}
Node summary: ${node.summary}
Node signature: ${node.signature ?? "N/A"}

Node contract:
${JSON.stringify(node.contract, null, 2)}

Related nodes:
${JSON.stringify(
  relatedNodes.map((candidate) => ({
    id: candidate.id,
    ownerId: candidate.ownerId,
    kind: candidate.kind,
    name: candidate.name,
    summary: candidate.summary,
    signature: candidate.signature,
    contract: candidate.contract
  })),
  null,
  2
)}

Relevant edges:
${JSON.stringify(relatedEdges, null, 2)}

${retrievalContext.used && retrievalContext.result
  ? `CodeRAG context:
${formatAgentRetrievalPrompt(retrievalContext.result)}

`
  : ""}

Current code:
\`\`\`
${body.currentCode}
\`\`\`

Extra instruction:
${body.instruction?.trim() || "Improve the implementation using the blueprint as the source of truth."}

Return the JSON suggestion now.`;
    const governedSystemPrompt = await withCodeflowGovernance(
      SYSTEM_PROMPT,
      "implementation"
    );

    let content: string;

    if (useOpencode || body.useOpencode) {
      const result = await sendToOpencode({
        systemPrompt: governedSystemPrompt,
        prompt: userPrompt,
      });

      if (!result.success) {
        throw new Error(result.error ?? "OpenCode request failed");
      }

      content = result.content ?? "";
    } else {
      content = await requestNvidiaChatCompletion({
        apiKey: apiKey!,
        messages: [
          { role: "system", content: governedSystemPrompt },
          { role: "user", content: userPrompt }
        ],
        temperature: 0.2,
        topP: 0.7,
        maxTokens: 4096
      });
    }

    const jsonMatch = content.match(/\{[\s\S]*\}/);
    const jsonString = jsonMatch ? jsonMatch[0] : content;
    const parsed = responseSchema.parse(JSON.parse(jsonString));
    const retrievalNote = formatAgentRetrievalNote(retrievalContext);

    console.info("[CodeFlow] Code suggestion generated", {
      nodeId: body.nodeId,
      durationMs: Date.now() - startedAt
    });

    return NextResponse.json({
      ...parsed,
      notes: retrievalNote ? [...parsed.notes, retrievalNote] : parsed.notes
    });
  } catch (error) {
    console.error("[CodeFlow] Failed to generate code suggestion", {
      durationMs: Date.now() - startedAt,
      error: error instanceof Error ? error.message : "Unknown error"
    });

    return NextResponse.json(
      { error: error instanceof Error ? error.message : "Failed to generate code suggestion." },
      { status: 400 }
    );
  }
}

