const normalizeEdgeKind = (
  rawKind: string | undefined,
  warnings: string[],
  context: string,
  fallbackKind?: BlueprintEdgeKind
): BlueprintEdgeKind | null => {
  if (!rawKind?.trim()) {
    return fallbackKind ?? null;
  }

  const normalizedToken = normalizeRelationKindToken(rawKind);
  const directKind = DIRECT_EDGE_KIND_MAP.get(normalizedToken);
  if (directKind) {
    return directKind;
  }

  const synonymKind =
    EDGE_KIND_SYNONYMS.get(normalizedToken) ??
    EDGE_KIND_SYNONYMS.get(normalizedToken.replace(/-/g, " "));
  if (synonymKind) {
    warnings.push(`Normalized AI ${context} kind "${rawKind}" to "${synonymKind}".`);
    return synonymKind;
  }

  warnings.push(
    `Dropped AI ${context} kind "${rawKind}" because it is not supported by the blueprint schema.`
  );
  return null;
};

const normalizeDesignCalls = (
  calls:
    | Array<{
        target: string;
        kind?: string;
        description?: string;
      }>
    | undefined,
  warnings: string[],
  context: string
): DesignCall[] =>
  (calls ?? []).map((call) => {
    const kind = normalizeEdgeKind(call.kind, warnings, `${context} call`);
    return {
      target: call.target,
      description: call.description,
      ...(kind ? { kind } : {})
    };
  });

const extractBalancedJsonObject = (input: string, startIndex: number): string | null => {
  let depth = 0;
  let inString = false;
  let isEscaped = false;

  for (let index = startIndex; index < input.length; index += 1) {
    const char = input[index];

    if (isEscaped) {
      isEscaped = false;
      continue;
    }

    if (char === "\\") {
      isEscaped = true;
      continue;
    }

    if (char === "\"") {
      inString = !inString;
      continue;
    }

    if (inString) {
      continue;
    }

    if (char === "{") {
      depth += 1;
      continue;
    }

    if (char === "}") {
      depth -= 1;
      if (depth === 0) {
        return input.slice(startIndex, index + 1);
      }
    }
  }

  return null;
};

const extractJsonObjectString = (content: string): string => {
  const fencedMatch = content.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const candidates = fencedMatch ? [fencedMatch[1] ?? "", content] : [content];

  for (const candidate of candidates) {
    for (let index = 0; index < candidate.length; index += 1) {
      if (candidate[index] !== "{") {
        continue;
      }

      const jsonCandidate = extractBalancedJsonObject(candidate, index);
      if (!jsonCandidate) {
        continue;
      }

      try {
        JSON.parse(jsonCandidate);
        return jsonCandidate;
      } catch {
        // Keep scanning until we find the first parseable JSON object.
      }
    }
  }

  throw new Error("Failed to locate a valid JSON object in the AI response.");
};

const normalizeAiBlueprint = (
  payload: z.infer<typeof aiBlueprintResponseSchema>,
  request: z.infer<typeof requestSchema>
): BlueprintGraph => {
  const generatedAt = new Date().toISOString();
  const warnings = [...payload.warnings];
  const normalizedNodes = payload.nodes.map((node) => {
    const name = node.name.trim();
    const contractSummary = node.contract?.summary?.trim();
    const summary = node.summary?.trim() || contractSummary || `Blueprint node for ${name}.`;

    return createNode({
      id: node.id?.trim() || createNodeId(node.kind, name, node.path ?? name),
      kind: node.kind,
      name,
      summary,
      path: node.path?.trim() || undefined,
      signature: node.signature?.trim() || undefined,
      ownerId: node.ownerId?.trim() || undefined,
      contract: {
        ...emptyContract(),
        summary,
        responsibilities: node.contract?.responsibilities ?? [],
        inputs: node.contract?.inputs ?? [],
        outputs: node.contract?.outputs ?? [],
        attributes: node.contract?.attributes ?? [],
        methods: (node.contract?.methods ?? []).map((method) => ({
          name: method.name,
          signature: method.signature?.trim() || undefined,
          summary: method.summary,
          inputs: method.inputs ?? [],
          outputs: method.outputs ?? [],
          sideEffects: method.sideEffects ?? [],
          calls: normalizeDesignCalls(
            method.calls,
            warnings,
            `method "${name}.${method.name}"`
          )
        })),
        sideEffects: node.contract?.sideEffects ?? [],
        errors: node.contract?.errors ?? [],
        dependencies: node.contract?.dependencies ?? [],
        calls: normalizeDesignCalls(node.contract?.calls, warnings, `node "${name}"`),
        uiAccess: node.contract?.uiAccess ?? [],
        backendAccess: node.contract?.backendAccess ?? [],
        notes: node.contract?.notes ?? []
      },
      sourceRefs:
        node.sourceRefs && node.sourceRefs.length
          ? node.sourceRefs
          : [{ kind: "generated", detail: "AI generated from prompt" }],
      generatedRefs: node.generatedRefs ?? [],
      traceRefs: node.traceRefs ?? []
    });
  });

  const nodeIdMap = new Map<string, string>();
  for (const node of normalizedNodes) {
    nodeIdMap.set(node.id, node.id);
    nodeIdMap.set(node.name, node.id);
  }

  const normalizedEdges = payload.edges
    .map((edge) => {
      const from = nodeIdMap.get(edge.from) ?? edge.from;
      const to = nodeIdMap.get(edge.to) ?? edge.to;

      if (!nodeIdMap.has(from) || !nodeIdMap.has(to)) {
        return null;
      }

      const normalizedKind = normalizeEdgeKind(
        edge.kind,
        warnings,
        `edge "${edge.from}" -> "${edge.to}"`,
        "calls"
      );
      if (!normalizedKind) {
        return null;
      }

      return {
        from,
        to,
        kind: normalizedKind,
        label: edge.label?.trim() || undefined,
        required: edge.required ?? true,
        confidence: edge.confidence ?? 0.65
      };
    })
    .filter((edge): edge is NonNullable<typeof edge> => Boolean(edge));

  if (normalizedNodes.length === 0) {
    throw new Error("The AI response did not contain any blueprint nodes. Try a more specific project description.");
  }

  return withSpecDrafts(
    blueprintGraphSchema.parse({
      projectName: request.projectName,
      mode: request.mode,
      phase: "spec",
      generatedAt,
      nodes: normalizedNodes,
      edges: normalizedEdges,
      workflows: payload.workflows,
      warnings
    })
  );
};

