      latestSpans: summary.latestSpans.slice(0, 10),
      latestLogs: summary.latestLogs.slice(0, 10)
    });
  } catch (error) {
    return NextResponse.json(
      {
        error: error instanceof Error ? error.message : "Failed to load observability snapshot."
      },
      { status: 400 }
    );
  }
}

