import { POST } from "@/app/api/refactor/detect/route";
import type { BlueprintGraph } from "@/lib/blueprint/schema";
import { emptyContract } from "@/lib/blueprint/schema";

const graph: BlueprintGraph = {
  projectName: "Refactor Detect Route",
  mode: "essential",
  generatedAt: "2026-03-26T00:00:00.000Z",
  warnings: [],
  workflows: [],
  nodes: [
    {
      id: "function:auth",
      kind: "function",
      name: "authenticate",
      summary: "Authenticate a user.",
      contract: {
        ...emptyContract(),
        calls: [{ target: "GET /users", kind: "calls" }]
      },
      sourceRefs: [],
      generatedRefs: [],
      traceRefs: []
    },
    {
      id: "api:users",
      kind: "api",
      name: "GET /users",
      summary: "Users API.",
      contract: emptyContract(),
      sourceRefs: [],
      generatedRefs: [],
      traceRefs: []
    }
  ],
  edges: []
};

describe("POST /api/refactor/detect", () => {
  it("returns graph-scoped drift metadata", async () => {
    const response = await POST(
      new Request("http://localhost/api/refactor/detect", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify(graph)
      })
    );
    const body = (await response.json()) as {
      report: { totalIssues: number; provenance: string; maturity: string; scope: string };
    };

    expect(response.status).toBe(200);
    expect(body.report.totalIssues).toBeGreaterThan(0);
    expect(body.report.provenance).toBe("deterministic");
    expect(body.report.maturity).toBe("preview");
    expect(body.report.scope).toBe("graph");
  });
});

import { NextResponse } from "next/server";

import { blueprintGraphSchema } from "@/lib/blueprint/schema";
import { detectDrift } from "@/lib/blueprint/refactor";

/**
 * POST /api/refactor/detect
 *
 * Body: {@link BlueprintGraph}
 *
 * Returns a {@link RefactorReport} that describes all detected drift issues:
 * - broken edges (referencing non-existent node IDs)
 * - missing edges (contract calls with no corresponding graph edge)
 * - signature drift (top-level node signature differs from first contract method)
 */
export async function POST(request: Request) {
  try {
    const graph = blueprintGraphSchema.parse(await request.json());
    const report = detectDrift(graph);

    return NextResponse.json({ report });
  } catch (error) {
    return NextResponse.json(
      {
        error: error instanceof Error ? error.message : "Failed to detect architectural drift."
      },
      { status: 400 }
    );
  }
}

